// ─── Main ─────────────────────────────────────────────────────────────────────
interface Props { data?: POData }

const PurchaseOrderPrint: React.FC<Props> = ({ data = MOCK_DATA }) => {
  // Phase 1: measure refs for header, infobox, footer, and one sample row
  const refHeader  = useRef<HTMLDivElement>(null)
  const refInfo    = useRef<HTMLDivElement>(null)
  const refFooter  = useRef<HTMLDivElement>(null)
  const refRow     = useRef<HTMLTableRowElement>(null)
  const refThead   = useRef<HTMLTableSectionElement>(null)

  // pages: null = not yet calculated
  const [pages, setPages] = useState<POItem[][] | null>(null)
  const [rowsLast, setRowsLast] = useState(12)

  useEffect(() => {
    const s = document.createElement('style')
    s.id = 'po-style'; s.textContent = CSS
    document.head.appendChild(s)
    return () => { document.getElementById('po-style')?.remove() }
  }, [])

  // After first render (measurement phase), calculate pages
  useEffect(() => {
    if (pages !== null) return   // already calculated
    if (!refHeader.current || !refInfo.current || !refFooter.current || !refRow.current || !refThead.current) return

    const pxToMm = (px: number) => px / MM_TO_PX

    const headerMm  = pxToMm(refHeader.current.getBoundingClientRect().height)
    const infoMm    = pxToMm(refInfo.current.getBoundingClientRect().height)
    const footerMm  = pxToMm(refFooter.current.getBoundingClientRect().height)
    const theadMm   = pxToMm(refThead.current.getBoundingClientRect().height)
    const rowMm     = pxToMm(refRow.current.getBoundingClientRect().height)

    const fixedMm        = headerMm + infoMm + theadMm   // always present
    const availOther     = PAGE_H_MM - fixedMm            // non-last pages (no footer)
    const availLast      = PAGE_H_MM - fixedMm - footerMm // last page (with footer)

    const rowsOther = Math.floor(availOther / rowMm)
    const rowsLast  = Math.floor(availLast  / rowMm)

    console.log(`[PO] header:${headerMm.toFixed(1)} info:${infoMm.toFixed(1)} footer:${footerMm.toFixed(1)} thead:${theadMm.toFixed(1)} row:${rowMm.toFixed(1)}mm`)
    console.log(`[PO] rowsOther:${rowsOther} rowsLast:${rowsLast}`)

    // Build page chunks
    const result: POItem[][] = []
    let i = 0
    const items = data.items
    while (i < items.length) {
      const isLast = i + rowsOther >= items.length
      const size   = isLast ? rowsLast : rowsOther
      result.push(items.slice(i, i + size))
      i += size
    }
    setRowsLast(rowsLast)
    setPages(result)
  })

  // ── PHASE 1: Measurement render (hidden, single-page skeleton) ──
  if (pages === null) {
    return ReactDOM.createPortal(
      <div className="po-portal">
        <div className="po-page" style={{visibility:'hidden'}}>
          <div ref={refHeader}><POHeader data={data} pageNum={1} totalPages={1}/></div>
          <div ref={refInfo}><POInfoBox data={data}/></div>
          <table className="po-tbl">
            {TABLE_COLS}
            <thead ref={refThead}>{TABLE_HEAD.props.children}</thead>
            <tbody>
              <tr ref={refRow}>
                <td>1</td><td>CODE</td>
                <td><div>Sample description text here</div><div style={{fontSize:'7pt'}}>sub desc</div></td>
                <td>10</td><td>เส้น</td><td>1,000.00</td><td>10,000.00</td>
              </tr>
            </tbody>
          </table>
          <div ref={refFooter}><POFooter data={data}/></div>
        </div>
      </div>,
      document.body
    )
  }

  // ── PHASE 2: Actual render with calculated pages ──
  const totalPages = pages.length

  return ReactDOM.createPortal(
    <div className="po-portal">
      {pages.map((pageItems, pageIdx) => {
        const isLast = pageIdx === totalPages - 1
        const rows = [...pageItems]
        // no padding needed - table flex:1 fills space, rows sit naturally at top

        return (
          <div key={pageIdx} className="po-page">
            <POHeader data={data} pageNum={pageIdx+1} totalPages={totalPages}/>
            <POInfoBox data={data}/>
            {isLast ? (
              <>
                {/* wrapper has the border, table inside has no border, spacer fills remaining space */}
                <div style={{ flex:1, display:'flex', flexDirection:'column', border:'1px solid #000', borderTop:'none' }}>
                  <table className="po-tbl-inner" style={{ width:'100%', borderCollapse:'collapse', tableLayout:'fixed' }}>
                    {TABLE_COLS}{TABLE_HEAD}
                    <tbody>{rows.map((row,i)=><ItemRow key={i} row={row}/>)}</tbody>
                  </table>
                  {/* spacer fills remaining space inside the bordered wrapper */}
                  <div style={{ flex:1 }} />
                </div>
                <POFooter data={data}/>
              </>
            ) : (
              <>
                {/* other pages: table stretches to fill entire remaining space */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                  <table className="po-tbl" style={{ flex: 1, height: '100%' }}>
                    {TABLE_COLS}{TABLE_HEAD}
                    <tbody className="stretch">
                      {rows.map((row,i)=><ItemRow key={i} row={row}/>)}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>
        )
      })}
    </div>,
    document.body
  )
}

export default PurchaseOrderPrint